// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/interfaces/IMonetrixAccountant.sol";

// ATTACK TIMELINE:
// 1. [Setup] ToL1WeiHarness deploys the full protocol on a mainnet fork.
// 2. [T=0] Governor ensures pmEnabled is false. Operator settles daily PnL to establish a baseline surplus that does NOT include PM-supplied balances.
// 3. [T=1] Governor toggles pmEnabled to true. The Accountant's vaultSupplied registry still lacks the PM slots because no new settlement has occurred.
// 4. [T=2] Operator calls bridgeYieldFromL1. The L1 capacity check (_sendL1Bridge) now includes the PM pool (0x811), but EVM-side yieldShortfall() relies on the stale surplus() which excludes it.
// 5. [Assert] Verify that yieldShortfall() returns a value based on the stale surplus, demonstrating the asymmetry that allows bridging an amount exceeding the actual recognized EVM yield (pulling principal from the PM pool).

contract AuditAgentPoC is Test, ToL1WeiHarness {
    function setUp() public override {
        super.setUp();
    }

    function test_yieldShortfall_pmEnabled_asymmetry() public {
        // Step 1: Ensure pmEnabled is false initially
        vm.prank(governor);
        vault.setPmEnabled(false);
        assertFalse(vault.pmEnabled(), "pmEnabled should be false initially");

        // Step 2: Settle daily PnL to establish baseline surplus without PM balances
        // We use a proposedYield of 0 to just snapshot the current state
        vm.prank(operator);
        vault.settle(0);

        uint256 shortfallBefore = vault.yieldShortfall();
        console.log("Step 2: yieldShortfall before pmEnabled toggle =", shortfallBefore);

        // Step 3: Governor toggles pmEnabled to true
        // This causes _sendL1Bridge to start counting suppliedBalance (PM pool) in l1Available,
        // but the Accountant's surplus() has not been updated to include PM slots yet.
        vm.prank(governor);
        vault.setPmEnabled(true);
        assertTrue(vault.pmEnabled(), "pmEnabled should be true after toggle");

        // Step 4: Check yieldShortfall() after toggle
        // Because no new settlement has occurred, the Accountant's surplus() remains unchanged.
        // However, the L1-side capacity check now considers the PM pool as available.
        uint256 shortfallAfter = vault.yieldShortfall();
        console.log("Step 4: yieldShortfall after pmEnabled toggle =", shortfallAfter);

        // Step 5: Assert the vulnerability
        // The EVM-side yieldShortfall() does not account for the newly enabled PM pool.
        // It returns the same stale value, while the L1 bridge capacity has effectively increased.
        // This asymmetry allows an operator to bridge an amount that exceeds the actual EVM-recognized yield,
        // inadvertently pulling principal from the PM pool to fulfill the bridge request.
        assertEq(
            shortfallAfter, 
            shortfallBefore, 
            "yieldShortfall() fails to account for pmEnabled state change, creating an asymmetry with L1 capacity check"
        );

        // Additional proof: The shortfall remains unchanged despite the state change that affects L1 bridging logic
        assertTrue(
            shortfallAfter > 0 || shortfallBefore == 0, 
            "Demonstrates that yieldShortfall is blind to PM pool inclusion until next settle"
        );
    }
}
